const e={meta:{title:"POP · Studioul creatorilor Fortnite"},nav:{features:"Funcționalități",boussole:"Boussole",pricing:"Prețuri",faq:"Întrebări",login:"Conectare",join:"Intră în beta",home:"POP, acasă",lang:"Limbă",search:"Caută o țară"},hero:{announce:"Nou: Boussole, asistentul integrat",h1a:"Hărțile tale Fortnite.",h1b:"Împreună. Fără haos.",subA:"POP adună tot studioul UEFN într-un singur loc: ",subB:"sarcini de o oră",subC:", Verse legat de UEFN, tablă albă, analiza pieței și împărțirea câștigurilor.",cta:"Intră pe lista de așteptare",see:"Vezi funcționalitățile",micro1:"Beta privată",micro2:"Acces pe lista de așteptare",micro3:"Legat de UEFN"},marquee:{label:"Funcționează cu instrumentele tale",epic:"API-ul Fortnite de la Epic"},pain:{eyebrow:"Problema",h2a:"Discord, trei Google Docs,",h2b:"și nimeni nu știe cine ce face.",without:"Fără POP",with:"Cu POP",bad:["„Cine s-a atins de spawner?”","Verse-ul circulă pe Discord în .txt","O listă de sarcini într-un Google Doc","Tabelul câștigurilor, versiunea 7","„Deci când lansăm?”","Construim fără să știm dacă genul merge"],good:["Fiecare acțiune e înregistrată și reversibilă","Ctrl+S trimite Verse-ul în UEFN","Sarcini de o oră, cu dependențe","Un extras clar pentru fiecare","Boussole urmărește etapele și întârzierile","Un verdict pe gen, cu cifre reale"]},feat:{eyebrow:"Funcționalități",h2:"Tot studioul, de la idee la ziua lansării.",p:"Ce vezi aici sunt ecranele reale din POP, simplificate.",items:[{tag:"Sarcini și Boussole",h:"Sarcini de o oră. Un asistent în fiecare dimineață.",p:"Generatorul împarte harta în sarcini de o oră, cu dependențele lor. Boussole rezumă ziua, semnalează întârzierile și propune ce să iei mai întâi.",pts:["Kanban și dependențe","Întârzieri și etape urmărite","„Preia” dintr-un clic"]},{tag:"Editor Verse",h:"Ctrl+S și e deja în UEFN.",p:"Verse-ul se scrie în POP și ajunge direct în proiect: compilare, erori la linia corectă, sesiune de test. Asistentul explică și corectează, fără serviciu extern.",pts:["Compilare în UEFN","Erori la linie","Corecturi propuse"]},{tag:"Organizator",h:"Toate dispozitivele. Ordonate în trei secunde.",p:"Caută după tag, tip sau dosar, selectează douăzeci și redenumește, mută sau duplică dintr-odată. Ctrl+Z anulează. Dacă UEFN e închis, modificările așteaptă.",pts:["Căutare tag:, type:, dosar:","Modificări în masă","Totul e reversibil"]},{tag:"Tablă albă",h:"Desenați harta împreună.",p:"Notițe, forme, săgeți, culori, aldin, subliniat: tot ce trebuie pentru idei. Votați, apoi transformați cele mai bune notițe în sarcini.",pts:["Formatare completă","Colaborare în timp real","Notițe → sarcini"]},{tag:"Analiză",h:"Află ce să construiești înainte să construiești.",p:"Ce genuri atrag jucători, unde e loc liber, ce hărți decolează de la lansare și ce e în trend pe video. Cifre din API-ul oficial Epic.",pts:["Verdict pe gen","Hărți care merg","Trenduri TikTok și Shorts"]},{tag:"Plăți",h:"Fiecare știe cât câștigă.",p:"Reguli de împărțire procentuale, fixe sau pe sarcină, import de câștiguri, extras pe persoană. Gata cu tabelele pierdute pe Discord.",pts:["Procent, fix, pe sarcină","Import CSV","Extrasul fiecăruia"]}],aiB:"Folosești deja o IA?",aiText:"Conectează Claude, Cursor, Codex sau altă IA compatibilă MCP: preia o sarcină, scrie Verse-ul, compilează, apoi închide sarcina cu o notă. Fiecare acțiune e înregistrată și reversibilă."},bou:{eyebrow:"Asistent integrat",h2a:"Pune întrebarea.",h2b:"Boussole răspunde.",p:"Boussole îți cunoaște sarcinile, etapele și echipa. Îți spune ce e întârziat, cine la ce lucrează și cu ce să începi, și îi ghidează pas cu pas pe cei care descoperă POP. Totul fără ca datele tale să părăsească POP.",sub:"asistent integrat",ask:"Cum fac să…?",demo:[{q:"Ce fac acum?",a:["**Bună, Léa, recuperăm întârzierea?**","[r] 2 sarcini sunt întârziate.","[g] Ieri ai terminat 3 sarcini.","Acum: **#42 Sistem de scor**, care deblochează alte 3 sarcini."]},{q:"Cum conectez UEFN?",a:["**Cum legi UEFN de POP?**","1. Organizator → Descarcă UEFN Link.","2. Dublu clic pe pop-link.exe pe PC.","3. În UEFN: Model Context Protocol → Start Server."]},{q:"Suntem în întârziere pentru beta?",a:["[o] Etapa „Beta” în 5 zile: mai sunt 9 sarcini.","În ritmul actual (1,5 pe zi), ar dura 6 zile. **Întârziere estimată: 1 zi.**"]},{q:"La ce lucrează Hugo?",a:["**Hugo** are 1 sarcină în lucru și 2 de făcut:","• **#38** Decor zona 2 · în lucru de ieri","• **#44** Ecran final · așteaptă #42","[g] 4 sarcini terminate săptămâna asta."]},{q:"IA mea poate închide sarcini?",a:["Da: conectată în „IA conectate”, folosește **next_task**, **set_task_status** și **comment_task**. Fiecare acțiune e marcată „IA” în istoric."]}]},stats:[["1 h","pe sarcină, ca să avansezi zilnic"],["0","servicii IA externe obligatorii"],["7 zile","de statistici pe hartă, din API-ul Epic"],["100%","din acțiunile UEFN reversibile"]],pricing:{eyebrow:"Prețuri",h2:"Alege-ți planul.",p:"POP e în beta privată: accesul se face pe lista de așteptare. Prețurile se aplică la lansare și vei fi anunțat înainte de orice plată.",perMonth:"/ lună",compare:"Compară planurile",unlimited:"Nelimitat",soon:"În curând",plans:[{name:"Creator",tag:"Pentru început",desc:"O hartă, o echipă mică, tot esențialul.",cta:"Intră pe listă"},{name:"Studio",tag:"Cel mai complet",desc:"Pentru studiourile care lansează hărți în echipă.",cta:"Intră pe listă"},{name:"Studio+",tag:"În curând",desc:"Tot din Studio, plus POP Forge: aplicația desktop care construiește în UEFN.",cta:"Intră pe listă"}],rows:["Organizare","Sarcini de o oră, Kanban, dependențe","Boussole, asistentul integrat","Pagini, tablă albă, planificare și etape","Hărți","Membri","UEFN","UEFN Link: proiecte sincronizate","Editor Verse legat (compilare, erori la linie)","Organizator de actori și modificări în masă","IA conectate (Claude, Cursor, Codex…)","POP Forge: construcție asistată în UEFN","Creștere","Analiza pieței și hărți care merg","Trenduri video TikTok și YouTube Shorts","Schimb de playtesturi și ziua lansării","Împărțirea câștigurilor și extrase","Discord, GitHub, Lore"]},faq:{eyebrow:"Întrebări",h2:"Întrebările pe care le primim.",items:[["Am nevoie de un PC cu Windows?","Pentru a lega UEFN, da: UEFN rulează doar pe Windows, iar UEFN Link pornește pe acel PC. Restul POP merge în orice browser, inclusiv pe Mac."],["POP îmi publică harta?","Nu. POP pregătește totul (verificare înainte de publicare, playtesturi, planul zilei lansării), dar publicarea se face mereu în portalul de creatori Epic."],["Cum funcționează asistentul Boussole?","Boussole e integrat în POP: îți citește sarcinile, datele, dependențele și etapele ca să rezume ziua, să răspundă la întrebări („ce e întârziat?”, „la ce lucrează Hugo?”) și să explice cum se folosește POP. Rulează în întregime în POP: datele tale nu pleacă spre niciun serviciu extern."],["Și dacă vreau să folosesc IA mea?","Conectează Claude, Cursor, Codex sau altă IA compatibilă MCP în „IA conectate”. Poate citi și modifica sarcinile, Verse-ul și actorii UEFN, iar fiecare acțiune e înregistrată și reversibilă."],["De unde vin cifrele din analiză?","Din API-ul oficial Fortnite de la Epic: jucători, vârf de jucători simultani, timp de joc și retenție pentru fiecare hartă publică, pe 7 zile."],["Cum obțin acces?","POP e în beta privată. Intră pe lista de așteptare: verificăm cererile una câte una și primești pe e-mail un link pentru a-ți crea contul."],["Cât costă?","Prețurile sunt afișate mai sus. Se aplică la deschiderea POP; membrii beta sunt anunțați înainte de orice plată."]]},final:{h2a:"Următoarea ta hartă",h2b:"începe aici.",p:"Intră pe lista de așteptare: îți trimitem accesul imediat ce se eliberează un loc."},foot:{made:"Făcut de creatori Fortnite, pentru creatori Fortnite.",legal:"Fortnite și UEFN sunt mărci comerciale ale Epic Games. POP nu este afiliat cu Epic Games și nici aprobat de aceasta.",product:"Produs",help:"Ajutor",account:"Cont"},mock:{overview:"Prezentare",nav:["Prezentare","Pagini","Tablă albă","Sarcini","Editor Verse","Organizator","Piață"],hello:"Bună, Léa, îți propun să începi cu #42.",late:"2 sarcini întârziate (cea mai veche era pe 12 nov.).",mile:"Etapa „Beta” în 5 zile: mai sunt 9 sarcini, întârziere estimată de 1 zi.",take:"Preia",start:"Începe",unlocks:"deblochează alte 3 sarcini",today:"termen azi",waits:"așteaptă #42",todo:"De făcut",doing:"În lucru",done:"Gata",tasks:["Sistem de scor","Decor zona 2","Ecran final","Playtest intern","Spawn jucători","Furtuna"],sent:"trimis în UEFN",err:"Linia 12: int și float nu se pot aduna.",fix:"Corectează: Points += 1",red:"Echipa roșie",selected:"2 selectate",rename:"Redenumește",move:"Mută",dup:"Duplică",s1:"Mod echipe 4v4",s2a:"Boss final",s2b:"în centru",s3:"Economie: 1 monedă / eliminare",verdicts:["Oportunitate bună","Popular, dar disputat","Saturat","Nișă"],typical:"jucători / hartă tipică",earnings:"Câștigurile din octombrie",roles:["Cod · 40%","Hartă · 35%","Muzică · fix","Rest"],noTransfer:"POP calculează, nu face niciun transfer."},wl:{eyebrow:"Beta privată",title:"Intră pe lista de așteptare",intro:"Deschidem POP treptat, ca să fim alături de fiecare studio. Spune-ne cine ești și îți trimitem accesul cât mai repede.",pageIntro:"Conturile POP se deschid pe bază de invitație. Spune-ne cine ești: vei primi un link pentru a-ți crea contul după ce accesul e aprobat.",invalid:"Acest link de acces e invalid, deja folosit sau expirat. Trimite o nouă cerere sau scrie echipei POP.",name:"Nume sau pseudonim",email:"E-mail",studio:"Studio",optional:"(opțional)",studioPh:"Numele studioului",team:"Mărimea echipei",teams:["Singur","2–3","4–10","Peste 10"],exp:"Experiență",exps:["Începător în UEFN","Câteva hărți publicate","Creator experimentat","Studio profesionist"],links:"Hărțile sau rețelele tale",linksPh:"Coduri de insulă, TikTok, YouTube…",msg:"Ce vrei să faci cu POP",msgPh:"Ex.: suntem 4 pe o hartă tycoon și ne pierdem între Discord și Google Docs.",send:"Cere acces",sending:"Se trimite…",nospam:"Fără spam: îți scriem doar ca să-ți dăm accesul.",okTitle:"Am notat, mulțumim!",okText:"Cererea ta a ajuns la echipa POP. Vei primi un link pentru a-ți crea contul imediat ce se eliberează un loc.",alreadyTitle:"Ești deja pe listă.",approvedTitle:"Accesul tău e deja aprobat.",approvedText:"Verifică-ți e-mailul: linkul pentru crearea contului a fost trimis. Dacă nu, scrie-ne.",close:"Închide"}};export{e as default};
